mapper.select:
SELECT EXISTS (
    SELECT 1 FROM COUPON WHERE coupon_code = #{couponCode}
)

mapper.insert:
INSERT INTO COUPON (
    coupon_code, coupon_name, discount_type, discount_value,
    min_order_amount, max_discount_amount, issue_type,
    valid_from, valid_to, usage_limit, issued_count, status
) VALUES (
    #{couponCode}, #{couponName}, #{discountType}, #{discountValue},
    #{minOrderAmount}, #{maxDiscountAmount}, #{issueType},
    #{validFrom}, #{validTo}, #{usageLimit}, #{issuedCount}, #{status}
)

mapper.update:
UPDATE COUPON
SET issued_count = issued_count + #{amount}
WHERE coupon_id = #{couponId}

UPDATE COUPON
SET status = #{status}
WHERE coupon_id = #{couponId}

mapper.select:
SELECT COUNT(*) FROM MEMBER m WHERE m.status = 'ACTIVE' AND m.email IN
#{email}
AND NOT EXISTS ( SELECT 1 FROM MEMBER_COUPON mc WHERE mc.coupon_id = #{couponId} AND mc.member_id = m.member_id )

mapper.insert:
INSERT INTO MEMBER_COUPON (coupon_id, member_id) SELECT #{couponId}, m.member_id FROM MEMBER m WHERE m.status = 'ACTIVE' AND m.email IN
#{email}
AND NOT EXISTS ( SELECT 1 FROM MEMBER_COUPON mc WHERE mc.coupon_id = #{couponId} AND mc.member_id = m.member_id )
